insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-08-06','verbeterd','Offertes','Voorvertoning van de offerte vult het scherm',
   'De voorvertoning van een offerte in het dossier gebruikt nu de volle hoogte van je scherm, zodat je in één oogopslag veel meer van de offerte ziet. Met de knop rechtsboven zet je de offerte over het hele venster; met Escape ga je terug.');
